import base64,io,tarfile,pathlib,hashlib
p=pathlib.Path("/app/webapp.py")
assert hashlib.sha256(p.read_bytes()).hexdigest()=='e6d20eb44a867771606412f81adfbf22f15ef9a494b0e908e2fa9ae22bfb698e'
tarfile.open(fileobj=io.BytesIO(base64.b64decode(''))).extractall("/app")
p=pathlib.Path("/app/app.py")
p.write_text(p.read_text()+"\nfrom leyenda_integration import install as _install_leyenda\n_install_leyenda(app, _arena_webapp)\n")
